ALTER TABLE "ticket_approvals" ADD FOREIGN KEY ("approver_id") REFERENCES "users" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "knowledge_base_articles" ADD FOREIGN KEY ("service_id") REFERENCES "service_catalog" ("id") DEFERRABLE INITIALLY IMMEDIATE;

